Url":"","social":{"instagram":"","facebook":"","linkedin":"","youtube":"","tiktok":""}},"store":{"enabled":false,"url":null,"label":"Loja Online","openInNewTab":true,"showInHeader":true,"showInHero":false},"seo":{"title":"Ponto Radical | Náutica, navegação e aventura em Angola","description":"Electrónica marítima, equipamento de convés, manutenção de embarcações e kitesurf. Representantes Garmin, Sea-Dog Line, Star brite, Rule e Duotone em Angola.","keywords":"náutica Angola, Garmin, Sea-Dog Line, Star brite, Rule, Duotone, kitesurf, equipamento marítimo, Luanda","ogImage":{"url":"https://images.unsplash.com/photo-1552160757-52790c6f4faf?auto=format&fit=crop&w=1200&q=80","alt":"Ponto Radical","mediaId":null},"siteUrl":""},"footer":{"tagline":"Equipamento náutico, navegação e desportos de aventura em Angola.","copyright":"© Ponto Radical. Todos os direitos reservados.","showSocial":true,"links":[]}}'::jsonb, 1);
